mutants.find:
if (kind !== 'tests') {
  // Either the entry is `full`, or nobody has classified it. Both run everything, which is the
  // safe direction and the reason an unmapped directory cannot silently become skippable.
  return { kind: 'full', why: path };
}

const seen = new Set([name, ...PACKAGE_SCANNERS]);
const queue = [name];
while (queue.length > 0) {
  const current = queue.pop();
  if (current === undefined) break;
  for (const dependent of DEPENDENTS.get(current) ?? []) {
    if (seen.has(dependent)) continue;
    seen.add(dependent);
    queue.push(dependent);
  }
}

if (!recordsWholeSuite(process.env)) {
  console.log(
    '[test-count] this run was narrowed to the packages the commit reaches, so it did not ' +
      'collect the suite -- the scan is left as the last full run wrote it',
  );
  return;
}

if (scope.kind === 'tests') {
  return [{ step: COUNT_STEP.label, why: 'a subset run cannot move the full-suite baseline' }];
}
return [];
